export function range(from, to, step = 1) {
    const len = Math.floor((to - from) / step) + 1;
    return Array(len).fill(0).map((_, idx) => from + (idx * step));
}
export function diffArrays(left, right) {
    const leftSet = new Set(left);
    const rightSet = new Set(right);
    const diff = new Set();
    for (const item of left) {
        if (!rightSet.has(item)) {
            diff.add(item);
        }
    }
    for (const item of right) {
        if (!leftSet.has(item)) {
            diff.add(item);
        }
    }
    return Array.from(diff);
}
export function copyWithout(arr, ...elements) {
    return arr.filter(item => elements.includes(item));
}
export function removeArrayElementInline(arr, ...elements) {
    for (const element of elements) {
        const index = arr.indexOf(element);
        if (index !== -1) {
            arr.splice(index, 1);
        }
    }
}
